public static boolean copyFolder(File source, File target, Logger log) {
    Path sourcePath = source.toPath();
    Path destPath = target.toPath();
    try (Stream<Path> files = Files.walk(sourcePath)) {
        files.forEachOrdered(src -> {
            try {
                Path destFile = destPath.resolve(sourcePath.relativize(src));
                if (Files.isDirectory(src)) {
                    // Create directory if it doesn't exist
                    if (!Files.exists(destFile)) {
                        Files.createDirectories(destFile);
                    }
                } else {
                    // Copy file to the new location
                    Files.copy(src, destFile, StandardCopyOption.REPLACE_EXISTING);
                }
            } catch (IOException e) {
                log.warning("Failed to copy: " + src.toString() + " -> " + e.getMessage());
            }
        });
        return true;
    } catch (IOException e) {
        log.warning("Failed to copy folder: " + e.getMessage());
        return false;
    }
}

